import React from 'react'

import {GitHubAvatar} from '@github-ui/github-avatar'
import {useGetHovercardAttributesForType} from '@github-ui/hovercards/use-get-hovercard-attributes-for-type'

import {clsx} from 'clsx'
import styles from './FileFrame.module.css'
import {ChevronDownIcon, ChevronUpIcon, GitBranchIcon} from '@primer/octicons-react'
import {IconButton, Link} from '@primer/react'

import {CenteredContent, EllipsisOverflow, TextWithIcon} from './UI'
import {FileContext} from './context'

export type FileEntity = {
  /** The url of the file */
  url: string
  /** The path of the file */
  path: string
  /** The commit hash of this file */
  commit_id: string
  /** Name With Owner */
  nwo: string
  /** The language of the file. Eg: rust */
  language?: string
  /** The color of the language. Eg: #FFD6CC */
  language_color?: string
  /** The ref of the file. Eg: main */
  ref: {value: string; label: string} | string
}

export type FileFrameProps = {
  entity: FileEntity
  /**Any additional metadata renders to place in the file frame header */
  decorations?: React.ReactNode
  /** The base path for constructing URLs if the file is hosted on a different domain */
  basePath?: string
}

export function FileFrame({entity, decorations, basePath = '', children}: React.PropsWithChildren<FileFrameProps>) {
  const [isOpen, toggleOpen] = React.useReducer(v => !v, true)

  const [owner, name] = entity.nwo.split('/', 2)

  const repoUrl = `${basePath}/${owner}/${name}`
  const avatarUrl = `${basePath}/${owner}.png`

  const repoTreeRef = typeof entity.ref === 'string' ? {value: entity.ref, label: entity.ref} : entity.ref

  const fileContextValue = React.useMemo(() => ({fileUrl: entity.url, repoUrl}), [entity.url, repoUrl])

  return (
    <div className={styles.fileFrame}>
      <Header isOpen={isOpen} toggleOpen={toggleOpen}>
        <CenteredContent className={styles.headerMainContent}>
          <GitHubAvatar src={avatarUrl} square size={20} className={styles.avatar} />
          <EllipsisOverflow title={`${owner}/${name} · ${entity.path}`}>
            <RepositoryLink href={repoUrl}>
              {owner}/{name}
            </RepositoryLink>
            &nbsp;·&nbsp;<FileLink href={entity.url}>{entity.path}</FileLink>
          </EllipsisOverflow>
        </CenteredContent>
        <CenteredContent className={styles.headerMetadata}>
          {decorations ? <>{decorations}&nbsp;·&nbsp;</> : null}
          {entity.language ? (
            <>
              <LangaugeBadge color={entity.language_color}>{entity.language}</LangaugeBadge>&nbsp;·&nbsp;
            </>
          ) : null}
          <RefLink href={`${repoUrl}/tree/${repoTreeRef.value}`}>{repoTreeRef.label}</RefLink>
        </CenteredContent>
      </Header>
      <FileContext value={fileContextValue}>{isOpen && <Body>{children}</Body>}</FileContext>
    </div>
  )
}

function Header({children, isOpen, toggleOpen}: React.PropsWithChildren<{isOpen: boolean; toggleOpen(): void}>) {
  return (
    <div className={clsx(styles.header, !isOpen && styles.headerClosed)}>
      <IconButton
        icon={isOpen ? ChevronDownIcon : ChevronUpIcon}
        onClick={toggleOpen}
        variant="invisible"
        size="small"
        aria-label="Open code snippet"
        className={styles.toggleButton}
      />
      {children}
    </div>
  )
}

function Body({children}: React.PropsWithChildren) {
  return <div className={styles.body}>{children}</div>
}

function RepositoryLink({href, children}: React.PropsWithChildren<{href: string}>) {
  const getHovercardAttributesForType = useGetHovercardAttributesForType()
  return (
    <Link
      href={href}
      {...getHovercardAttributesForType('repository', {url: `${href}/hovercard`})}
      className={styles.repositoryLink}
      data-testid="code-link-to-repo"
    >
      {children}
    </Link>
  )
}

function FileLink({href, children}: React.PropsWithChildren<{href: string}>) {
  return (
    <Link href={href} className={styles.fileLink} data-testid="code-link-to-file">
      {children}
    </Link>
  )
}

function LangaugeBadge(props: React.PropsWithChildren<{color?: string}>) {
  const langagueColorElement = (
    <span aria-hidden className={styles.languageBadge} style={props.color ? {background: props.color} : undefined} />
  )

  return (
    <TextWithIcon icon={langagueColorElement} className={styles.mutedText}>
      {props.children}
    </TextWithIcon>
  )
}

function RefLink(props: React.PropsWithChildren<{href: string}>) {
  return (
    <Link href={props.href} className={styles.refLink}>
      <TextWithIcon icon={<GitBranchIcon size={16} aria-hidden />} className={styles.mutedText}>
        {props.children}
      </TextWithIcon>
    </Link>
  )
}
